function ConsentForm() {
  const [agreed, setAgreed] = useState(false);
  const [error, setError] = useState("");
  const [submitted, setSubmitted] = useState(false);

  const checkboxRef = useRef(null);
  const checkboxId = useId();
  const helpId = `${checkboxId}-help`;
  const errorId = `${checkboxId}-error`;

  const handleSubmit = (event) => {
    event.preventDefault();
    if (!agreed) {
      setError("Error: You must agree to the terms of use to continue.");
      setSubmitted(false);
      checkboxRef.current?.focus();
      return;
    }
    setError("");
    setSubmitted(true);
  };

  const handleChange = (event) => {
    setAgreed(event.target.checked);
    if (event.target.checked && error) setError("");
  };

  const describedBy = error ? `${helpId} ${errorId}` : helpId;

  return (
    <section className="card" aria-labelledby="form-title">
      <h1 id="form-title">Create your account</h1>
      <p className="lede">One last step before you get started.</p>

      {submitted && (
        <p className="status" role="status">
          Thanks — your agreement has been recorded.
        </p>
      )}

      <p className="required-legend">
        Fields marked with <span className="required-marker" aria-hidden="true">*</span> are required.
      </p>

      <form noValidate onSubmit={handleSubmit}>
        <div className="form-field">
          <div className="checkbox-row">
            <input
              ref={checkboxRef}
              id={checkboxId}
              type="checkbox"
              required
              checked={agreed}
              onChange={handleChange}
              aria-describedby={describedBy}
              aria-invalid={error ? "true" : undefined}
            />
            <label htmlFor={checkboxId}>
              I agree to the{" "}
              <a href="/terms" target="_blank" rel="noopener noreferrer">
                terms of use
              </a>
              <span className="required-marker" aria-hidden="true">*</span>
            </label>
            <p id={helpId} className="help-text">
              You must accept the terms before creating your account.
            </p>
            {error && (
              <p id={errorId} className="error-text">
                {error}
              </p>
            )}
          </div>
        </div>

        <div className="actions">
          <button type="submit">Create account</button>
        </div>
      </form>
    </section>
  );
}

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(<ConsentForm />);
